    description: "红火蚁工蚁体长约 2–6 mm，体红褐色，腹部颜色较深，同巢个体大小差异明显，可分为小型工蚁和大型工蚁。蚁巢在草地上隆起成松软的土丘，无明显出入口，受惊时成百上千只工蚁会迅速涌出，用尾刺连续蜇刺入侵者。\n\n红火蚁食性庞杂，捕食昆虫、蚯蚓、小型脊椎动物，也取食种子、蜜露和腐肉，常攻击雏鸟、蜥蜴等地面活动的小动物。成熟蚁巢可容纳数十万只工蚁，蚁后日产卵可达约 800–1000 枚，多蚁后型巢群密度更高。它原产南美巴拉那河流域，随苗木、草皮和货物运输扩散到美国、澳大利亚、中国南方等地，2004 年在中国广东首次确认，已被列入中国外来入侵物种名单。防治需检疫封锁、毒饵诱杀和蚁巢处理相结合。",
    habitat: "温暖湿润的草地、荒地、农田与城镇绿地，筑丘状蚁巢",
    distribution: "原产南美，现扩散至美国、澳大利亚及中国南方等地",
