    description: "家白蚁有翅繁殖蚁体长约 1.4–1.6 cm，黄褐色，四翅等长，翅长明显超过身体；工蚁和兵蚁体白色，兵蚁上颚发达，受惊时会分泌乳白色防御液体，家白蚁之名由此而来。群体在地下筑巢，通过泥被和泥线一样的蚁路取食。\n\n群体由一对原始蚁王和蚁后建立，蚁后腹部膨大，寿命可超过 10 年，日产卵数百至上千枚，成熟群体可达数百万只。工蚁啃食木材，消化道内的共生微生物能分解纤维素。家白蚁原产东亚，是中国南方和台湾地区的常见害虫，并随木材贸易传入美国、日本、南非等地，成为全球性入侵木材害虫，蛀食建筑木构件、堤坝、电缆和活树，造成重大经济损失。防治主要依靠诱杀饵剂、土壤药剂屏障和长期监测。",
    habitat: "地下巢系，常筑巢于潮湿土壤、建筑地基与树木根部",
