    description: "乌桕大蚕蛾翅展约 25–30 cm，雌蛾比雄蛾更大，是翅面积最大的蛾类之一。翅面红褐至橙褐色，布满白色波纹和半透明窗斑，前翅端部向外突出，形似蛇头，翅缘呈波浪状，整体像一片枯叶。\n\n幼虫取食乌桕、樟树、柑橘、番石榴等多种植物的叶片，幼虫期约 1–2 个月，老熟后吐丝结成大型茧。成虫羽化后口器退化，不再进食，只靠幼虫期积累的营养存活，寿命仅约 1–2 周，唯一任务是交配产卵。它在印度阿萨姆等地曾被半野生饲养，用于抽取蚕丝。乌桕大蚕蛾分布于中国南方、东南亚、印度次大陆和印度尼西亚的热带亚热带森林，前翅端部的蛇头斑纹被认为可以吓退天敌，它也是夜间观察和生态摄影的热门对象。",
