    description: "长戟犀金龟雄虫连同头角和胸角总长可达 17 cm 以上，是已知体长最长的甲虫之一；头部一根长角向上弯曲，前胸背板另有一根长角向前伸出，两角相对如长戟，因此得名。雌虫没有长角，体型较小，体黑褐色，鞘翅常有黄褐色或灰白色粉状斑纹。\n\n幼虫在腐木和腐殖土中生活，取食朽木，幼虫期可长达 1–2 年；成虫夜间活动，有趋光性，吸食树液和腐果，寿命约数个月。雄虫用长角互相夹斗，争夺树液和雌虫。长戟犀金龟分布于中南美洲的热带雨林，从墨西哥南部到厄瓜多尔、巴西等地，是当地雨林甲虫中的代表种类。由于体型巨大、外形威武，它成为全球最受欢迎的饲养甲虫之一，野生个体也受到标本贸易和宠物贸易的压力。",
