    description: "神圣蜣螂成虫体长约 2–3 cm，体黑色，体形圆厚，前足胫节宽扁带齿，适合掘粪和推球；鞘翅光滑，触角末端的鳃片可感知气味。\n\n它以动物粪便为食，会把粪便滚成球推到远处埋入地下，既取食又为幼虫储备食物；雌虫在粪球中产卵，幼虫孵化后以粪球为食。神圣蜣螂能利用太阳、月光和偏振光导航，在夜间也能保持直线行进，是导航研究中的经典昆虫。它分布在欧洲南部、北非和中亚的地中海气候区。古埃及人把蜣螂滚粪球与太阳运行联系起来，视其为太阳神凯布利的象征，称为圣甲虫，其形象大量出现在印章、护身符和壁画中。在草原上，它们是清理牲畜粪便的重要力量。",
