    description: "明亮熊蜂工蜂体长约 1.4–1.8 cm，蜂王更大，约 2.2–2.7 cm，体粗壮，全身密被绒毛，胸部黄色，腹部末端白色，因此又称白尾熊蜂；体表多毛可帮助它在低温下保温。\n\n熊蜂一年一代，蜂王春季单独寻找旧鼠洞或土洞筑巢，先产卵并独自哺育第一批工蜂，之后由工蜂不断扩大群体，秋季产生雄蜂和新蜂王，交配后只有新蜂王越冬，巢群规模通常只有几十到几百只。它取食花蜜和花粉，靠振动翅膀进行震动传粉，能把花粉从番茄等花药管中震出，授粉效率高于蜜蜂，因此被广泛用于温室番茄、茄子等作物授粉。明亮熊蜂分布于欧亚大陆，是重要的野生传粉者。",
