    description: "威氏行军蚁工蚁体长可达 1–1.5 cm，体红褐色，头部大、上颚镰刀状，分为多个体型等级，兵蚁的头部巨大，适合搬运和防御，蚁后腹部膨大，随群体迁移，工蚁用身体保护蚁后和幼虫。\n\n行军蚁不筑固定巢穴，而是形成由工蚁相互钩连而成的蚁团夜宿，白天成群出猎，以扇形队列扫过林下落叶层，捕食昆虫、蜘蛛、蜈蚣等小型动物，甚至攻击蜥蜴和雏鸟。群体规模可达数十万只，每天迁移一段距离。它分布在中美洲和南美洲的热带雨林，是雨林落叶层中的顶级捕食者之一。行军蚁的迁徙会带动其他生物活动，许多鸟类会跟随蚁群捕食被惊起的猎物，形成独特的生态现象。",
