    summary: "翅面淡绿、后翅有细长尾突的大型蚕蛾，形似月神，成虫不取食，幼虫取食枫杨等阔叶树，中国南方常见。",
    description: "绿尾大蚕蛾翅展约 10–13 cm，翅面淡绿色至粉绿色，前翅前缘有褐色带，各翅中央有一个淡黄色或粉色的月牙形斑，后翅拖着两条细长的尾突，整体像一只优雅的月神。雌蛾体型比雄蛾大，触角羽状。\n\n它生活在阔叶林、林缘和果园附近，成虫在夜间活动，有趋光性，口器退化，不取食，寿命只有约 1–2 周，主要靠幼虫期积累的营养完成交配产卵。幼虫取食枫杨、柳树、核桃等阔叶树叶片，体型肥大，体色绿色，身体带瘤突。绿尾大蚕蛾分布于中国南方、日本、朝鲜半岛和东南亚，是亚洲著名的观赏蛾类，也常被灯光吸引到人类住所附近。它的茧为褐色，结在寄主植物上。",
    habitat: "阔叶林、林缘与果园，枫杨、柳树等寄主植物附近",
