      { label: "翅展", value: "成虫约 1.5–2 cm，幼虫约 1 cm" },
      { label: "识别", value: "成虫停歇时像小菱形，幼虫受惊吐丝下垂" },
      { label: "生活史", value: "一年多代、世代重叠，繁殖速度快" },
      { label: "防治", value: "轮作、防虫网、性诱剂、生物农药和交替用药" }
