    description: "黄猄蚁工蚁体长约 7–10 mm，体橙黄至红褐色，身体细长，足长，善于在树枝间快速爬行。工蚁分大型和小型两类，大型工蚁负责防卫和捕猎，小型工蚁负责育幼和筑巢。蚁后体形较大，深褐色。\n\n它生活在亚洲热带和亚热带地区的树冠层，用幼虫吐出的丝把新鲜树叶缝合起来，做成悬挂在树上的巢，群体可分布在多棵树上。黄猄蚁是凶猛的捕食者，捕食蛾类幼虫、甲虫、蝗虫等害虫，因此被用于柑橘等果园的生物防治，中国南方和东南亚有利用黄猄蚁防治柑橘害虫的传统。它也会攻击接触巢穴的人，被咬后会疼痛，观察时要保持距离。",
