    description: "黑翅土白蚁有翅繁殖蚁体长约 1.5 cm，体黑褐色，四翅黑褐色、等长；工蚁体白色，头部圆形；兵蚁头部黄色，上颚发达呈镰刀状。群体在地下筑巢，巢内培育菌圃，用来分解植物材料。\n\n它生活在中国南方的丘陵、林地和堤坝附近，取食枯木、落叶和活树根部，工蚁把植物材料带回巢中培育真菌，幼虫和蚁后取食菌圃。黑翅土白蚁对堤坝、水闸和树木有一定危害，被称为土栖性白蚁，是水利工程和林业的重点防治对象；同时在森林生态中，它能分解枯木、促进物质循环。防治以诱杀、药物屏障和定期检查为主，堤坝上发现白蚁巢要及时处理。",
