    description: "牛虻成虫体长约 1.5–2.5 cm，体粗壮，头部大，复眼发达，雄虻复眼相接，雌虻复眼分离；体色灰褐或黑褐，腹部有斑纹，翅透明，足粗壮。雌虻口器为刺舐式，能刺破皮肤吸血。\n\n它生活在牧场、林缘、湿地和牲畜活动区，雄虻吸食花蜜，雌虻需要吸血来促进卵发育，会叮咬牛、马等牲畜和人类，叮咬时疼痛明显，还可能传播炭疽、锥虫病等疾病。牛虻飞行力强，能追踪移动的牲畜，是牧场的常见害虫，也影响户外活动和旅游。防治以畜体喷洒驱虫剂、诱捕器、清理孳生地为主，野外活动时穿长袖长裤并涂抹驱虫剂可减少叮咬，被叮咬后注意清洁伤口。",
