    description: "大蚊成虫体长约 2–3 cm，腿极长，展开时可达 10 cm 以上，外形像一只巨大的蚊子，但身体细弱，翅透明，停歇时双翅平展或呈八字形。它的口器退化，不能吸血，与真正的蚊子不同。\n\n大蚊生活在草丛、林缘、湿地、水边和花园，成虫寿命很短，多数不取食或只吸食少量水分和花蜜，主要任务是交配产卵。幼虫生活在潮湿的土壤、腐殖质、落叶层和水边泥中，取食腐烂植物和有机碎屑，是分解者之一。大蚊广布欧洲和亚洲，常见于雨后和潮湿环境，因体型大、腿长而常被误认为巨型蚊子，实际上对人无害，不需要防治。",
