    description: "褐飞虱成虫体长约 4–5 mm，有长翅型和短翅型两种，长翅型能迁飞，短翅型繁殖力强；体色黄褐至黑褐色，前胸背板和中胸背板有浅色斑。若虫体色灰白至黄褐，群集在稻株基部。\n\n它专食水稻，成虫和若虫群集在稻株基部和叶鞘上刺吸汁液，大量发生时导致稻株枯死、倒伏，形成“冒穿”现象，造成严重减产。褐飞虱具有迁飞性，夏季随季风从南方迁入中国稻区，秋季回迁，是中国水稻上的重大害虫之一。防治以监测预警、抗虫品种、保护天敌、科学用药和稻田生态调控为主，在低龄若虫高峰前施药效果最好。",
