    summary: "中国常见的散白蚁之一，工蚁体色浅黄，群体生活在木质构件和潮湿土壤中，是危害房屋木结构的白蚁种类。",
    description: "黄胸散白蚁工蚁体长 3–4 mm，体色乳白至浅黄，头部圆形，触角念珠状，没有翅；兵蚁上颚发达，头部呈黄色，负责防御。有翅繁殖蚁在春夏之交分飞，体色深褐，翅长超过身体，分飞后脱翅配对，寻找合适场所建立新群体。\n\n它分布在中国长江流域及以南地区，也见于日本，喜欢温暖潮湿的环境，群体常生活在房屋木构件、地板、门框、树桩和潮湿土壤中，取食木材中的纤维素。散白蚁群体较小，没有明显的集中巢，常常多点危害，因此不易彻底清除，是白蚁防治中的难点。它属于等翅目昆虫，与蚂蚁的亲缘关系并不近；分飞期通常在 4–6 月的闷热傍晚。目前尚无保护评估，防治主要依靠监测、诱杀和化学屏障。",
    habitat: "房屋木构件、地板、门框、树桩和潮湿土壤中",
