      { label: "繁殖", value: "春夏之交分飞，脱翅配对后建立新群体" },
      { label: "习性", value: "群体较小，无集中巢，常多点危害" },
      { label: "危害", value: "蛀食房屋木结构，是重要白蚁害虫" }
